const [mcp, local] = await Promise.allSettled([
  tools.opencode.list_mcp_resources(),
  (async () => {
    const out = [];
    for (const url of [
      "http://localhost:8080/",
      "http://127.0.0.1:8080/",
      "http://localhost:5000/",
      "http://127.0.0.1:3000/",
    ]) {
      try {
        const r = await fetch(url);
        out.push({ url, status: r.status });
      } catch (e) {
        out.push({ url, error: String(e) });
      }
    }
    return out;
  })(),
]);
return {
  mcp: mcp.status === 'fulfilled' ? mcp.value : mcp.reason,
  local: local.status === 'fulfilled' ? local.value : local.reason,
};

