cd /work && awk '
{
  # strip comments
  gsub(/<!--.*-->/, "")
  # count opening tags (self-closing excluded)
  n = match($0, /<[^\/!][^>]*[^\/]>$/)
  while (match($0, /<([a-zA-Z][a-zA-Z0-9]*)[^>]*>/)) {
    tag = substr($0, RSTART+1, RLENGTH)
    sub(/>.*$/, "", tag)
    if (tag ~ /\/$/) { selfclose++ } else { open[tag]++ }
    $0 = substr($0, RSTART+RLENGTH)
  }
  while (match($0, /<\/([a-zA-Z][a-zA-Z0-9]*)>/)) {
    tag = substr($0, RSTART+3, RLENGTH-4)
    close[tag]++
    $0 = substr($0, RSTART+RLENGTH)
  }
}
END {
  bad = 0
  for (t in open) {
    c = (t in close) ? close[t] : 0
    if (open[t] != c) { printf "MISMATCH %s open=%d close=%d\n", t, open[t], c; bad=1 }
  }
  for (t in close) if (!(t in open)) { printf "EXTRA CLOSE %s\n", t; bad=1 }
  if (!bad) print "OK: all tags balanced"
}' SystemContext.svg && ls -la SystemContext.svg

